export function endpointPath<K extends OperationID>(id: K, params: Operations[K]['pathParams']): string {
  return endpoints[id].path.replace(/\{([^}]+)\}/g, (_match, name: string) => {
    const value = (params as Record<string, string>)[name];
    if (value === undefined) throw new Error(`Missing path parameter: ${name}`);
    return encodeURIComponent(value);
  });
}
